    for f in report["fields"]:
        lines.append(f"| {f['source']} | {f['field']} | {f['outcome']} | {f['score']} | {f['confidence']} |")
    lines += [
        "",
        "## Validation",
        "",
        "| Document | Expected errors | Raised errors | Missed | Extra |",
        "|---|---|---|---|---|",
